// QueryAgentToken queries the agent_token edge of a AgentDMMessage.
func (c *AgentDMMessageClient) QueryAgentToken(_m *AgentDMMessage) *AgentTokenQuery {
	query := (&AgentTokenClient{config: c.config}).Query()
	query.path = func(context.Context) (fromV *sql.Selector, _ error) {
		id := _m.ID
		step := sqlgraph.NewStep(
			sqlgraph.From(agentdmmessage.Table, agentdmmessage.FieldID, id),
			sqlgraph.To(agenttoken.Table, agenttoken.FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, agentdmmessage.AgentTokenTable, agentdmmessage.AgentTokenColumn),
		)
		fromV = sqlgraph.Neighbors(_m.driver.Dialect(), step)
		return fromV, nil
	}
	return query
}

